package imaging

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"io"
	"io/fs"
	"os"
	"path/filepath"
)

// Store keeps processed images as <dir>/<id>.webp. Ids are 32 lower-case hex
// characters, generated by Save; anything else is rejected, so an id taken from
// a URL can never escape the directory.
type Store struct{ dir string }

// NewStore returns a Store over dir (created on first Save).
func NewStore(dir string) *Store { return &Store{dir: dir} }

// ValidID reports whether id has the shape Save generates.
func ValidID(id string) bool {
	if len(id) != 32 {
		return false
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

func (s *Store) path(id string) string { return filepath.Join(s.dir, id+".webp") }

// Save writes data under a new random id, atomically (temp file + rename).
func (s *Store) Save(data []byte) (string, error) {
	if err := os.MkdirAll(s.dir, 0o755); err != nil {
		return "", err
	}
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", err
	}
	id := hex.EncodeToString(raw[:])
	tmp, err := os.CreateTemp(s.dir, ".tmp-*")
	if err != nil {
		return "", err
	}
	defer os.Remove(tmp.Name()) // no-op once renamed
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return "", err
	}
	if err := tmp.Close(); err != nil {
		return "", err
	}
	if err := os.Rename(tmp.Name(), s.path(id)); err != nil {
		return "", err
	}
	return id, nil
}

// Open returns the file for id; ErrNotFound when missing or id is invalid.
func (s *Store) Open(id string) (ReadSeekCloser, error) {
	if !ValidID(id) {
		return nil, ErrNotFound
	}
	f, err := os.Open(s.path(id))
	if errors.Is(err, fs.ErrNotExist) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return f, nil
}

// Exists reports whether a file is stored for id.
func (s *Store) Exists(id string) bool {
	if !ValidID(id) {
		return false
	}
	_, err := os.Stat(s.path(id))
	return err == nil
}

// Delete removes the file for id; missing files and invalid ids are not errors.
func (s *Store) Delete(id string) error {
	if !ValidID(id) {
		return nil
	}
	if err := os.Remove(s.path(id)); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	return nil
}

// ReadSeekCloser lets http.ServeContent serve a stored image.
type ReadSeekCloser interface {
	io.Reader
	io.Seeker
	io.Closer
}
